#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int main() {
    int n;
    long long b;
    std::cin >> n >> b;
    std::vector<int> a(n);
    std::vector<int> c(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i];
        c[i] = (a[i] % 2 == 0) ? 1 : -1;
    }
    long long sum = 0;
    std::vector<int> differences;
    for (int i = 0; i < n - 1; ++i) {
        sum += c[i];
        if (sum == 0) {
            differences.push_back(std::abs(a[i] - a[i + 1]));
        }
    }
    std::sort(differences.begin(), differences.end());
    long long totalCost = 0;
    int count = 0;
    for (int diff : differences) {
        totalCost += diff;
        if (totalCost <= b) {
            ++count;
        } else {
            break;
        }
    }
    std::cout << count << std::endl;
    return 0;
}
